
const cfg=window.VERTICE_CONFIG||{};
const sb=supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_PUBLISHABLE_KEY);
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=v=>Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
const digits=v=>String(v||"").replace(/\D/g,"");
const cpf=v=>{v=digits(v).slice(0,11);return v.replace(/(\d{3})(\d)/,"$1.$2").replace(/(\d{3})(\d)/,"$1.$2").replace(/(\d{3})(\d{1,2})$/,"$1-$2")};
const cep=v=>{v=digits(v).slice(0,8);return v.replace(/(\d{5})(\d)/,"$1-$2")};
const phone=v=>{v=digits(v).slice(0,11);return v.length<=10?v.replace(/^(\d{2})(\d)/,"($1) $2").replace(/(\d{4})(\d)/,"$1-$2"):v.replace(/^(\d{2})(\d)/,"($1) $2").replace(/(\d{5})(\d)/,"$1-$2")};
let C={leads:[],clientes:[],orcamentos:[],materiais:[],custos:[],producao:[],tarefas:[],interacoes:[],chapas:[],ferragens:[],funcoes:[],origens:[],funcionarios:[],transacoes:[],configs:{}}; let QM=[],QMO=[],QP=[];

document.addEventListener("DOMContentLoaded",init);
async function init(){
 $("#today").textContent=new Date().toLocaleDateString("pt-BR",{weekday:"long",day:"2-digit",month:"long"});
 $("#loginForm").onsubmit=login; $("#logoutBtn").onclick=()=>sb.auth.signOut();
 $("#collapseBtn").onclick=()=>$("#sidebar").classList.toggle("collapsed");
 $$("nav button").forEach(b=>b.onclick=()=>page(b.dataset.page));
 sb.auth.onAuthStateChange((_e,s)=>sessionUI(s));
 const {data:{session}}=await sb.auth.getSession();sessionUI(session);
}
async function login(e){e.preventDefault();$("#loginMsg").textContent="";let {error}=await sb.auth.signInWithPassword({email:$("#loginEmail").value,password:$("#loginPassword").value});if(error)$("#loginMsg").textContent=error.message}
async function sessionUI(s){$("#login").classList.toggle("hidden",!!s);$("#app").classList.toggle("hidden",!s);if(s){await load();page("dashboard")}}
async function q(t){
 if(t==="orcamentos"){let {data,error}=await sb.rpc("listar_orcamentos_seguros");if(error){console.warn(t,error.message);return[]}return Array.isArray(data)?data:[]}
 let {data,error}=await sb.from(t).select("*");if(error){console.warn(t,error.message);return[]}return data||[]
}
async function load(){
 [C.leads,C.clientes,C.orcamentos,C.materiais,C.custos,C.producao,C.tarefas,C.interacoes,C.chapas,C.ferragens,C.funcoes,C.origens,C.funcionarios,C.transacoes]=await Promise.all(["crm_leads","clientes","orcamentos","materiais","custos_operacionais","producao","crm_tarefas","crm_interacoes","chapas_mdf","ferragens","mao_obra_funcoes","origens_lead","funcionarios","transacoes"].map(q));
 let cg=await q("config_global");C.configs=Object.fromEntries(cg.map(x=>[x.chave,Number(x.valor)]));
}
function page(name){
 $$("nav button").forEach(b=>b.classList.toggle("active",b.dataset.page===name));
 const names={dashboard:"Dashboard",leads:"Leads / CRM",clientes:"Clientes",pipeline:"Pipeline",agenda:"Agenda / Retornos",orcamentos:"Orçamentos",producao:"Produção",materiais:"Materiais",custos:"Cadastros e custos",financeiro:"Financeiro",relatorios:"Relatórios"};
 $("#pageTitle").textContent=names[name]||name;
 ({dashboard,leads,clientes,pipeline,agenda,orcamentos,producao,materiais,custos,financeiro,relatorios}[name]||dashboard)();
}
function panel(title,body,action=""){return `<div class=panel><div class=panel-head><h3>${title}</h3>${action}</div><div class=panel-body>${body}</div></div>`}
function table(headers,rows){return `<div class=table-wrap><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table></div>`}
function dashboard(){
 let active=C.leads.filter(x=>x.status==="Ativo").length, pipe=C.leads.filter(x=>!["Fechado","Perdido"].includes(x.etapa)).reduce((s,x)=>s+Number(x.valor_potencial||0),0);
 let approved=C.orcamentos.filter(x=>String(x.status).toLowerCase().includes("aprov")).reduce((s,x)=>s+Number(x.preco_final||0),0);
 let overdue=C.tarefas.filter(x=>x.status!=="Concluída"&&new Date(x.vencimento)<new Date()).length;
 $("#content").innerHTML=`<div class=cards>
 <div class="card metric"><span>Leads ativos</span><b>${active}</b><i>CRM</i></div>
 <div class="card metric"><span>Pipeline estimado</span><b>${money(pipe)}</b><i>Oportunidades</i></div>
 <div class="card metric"><span>Orçamentos aprovados</span><b>${money(approved)}</b><i>Vendas</i></div>
 <div class="card metric"><span>Retornos atrasados</span><b>${overdue}</b><i>Agenda</i></div></div>
 ${panel("Próximas produções",table(["Cliente","Projeto","Início","Conclusão","Status"],C.producao.slice().sort((a,b)=>(a.inicio_previsto||"").localeCompare(b.inicio_previsto||"")).slice(0,8).map(p=>`<tr><td>${esc(p.cliente_nome)}</td><td>${esc(p.projeto)}</td><td>${date(p.inicio_previsto)}</td><td>${date(p.conclusao_prevista)}</td><td><span class="badge gold">${esc(p.status)}</span></td></tr>`).join("")))}
 ${panel("Orçamentos recentes",quoteTable(C.orcamentos.slice().sort((a,b)=>b.id-a.id).slice(0,8)))}`;
}
function classLabel(c){return ({"A":"A — Alta prioridade","B":"B — Boa oportunidade","C":"C — Em acompanhamento","D":"D — Baixa prioridade"}[c]||c||"—")}
function leads(){
 $("#content").innerHTML=panel("Leads e oportunidades",table(["Cliente","Origem","Projeto","Etapa","Classificação","Valor","Próximo contato","Ações"],C.leads.map(l=>`<tr><td><b>${esc(l.nome)}</b><br><small>${esc(phone(l.telefone))}</small></td><td>${esc(l.origem||"")}</td><td>${esc(l.ambiente_interesse||"")}</td><td><span class=badge>${esc(l.etapa)}</span></td><td title="A: alta prioridade • B: boa oportunidade • C: acompanhamento • D: baixa prioridade">${esc(classLabel(l.classificacao))}</td><td>${money(l.valor_potencial)}</td><td>${dt(l.proximo_contato_em)}</td><td><div class=toolbar><button class="btn small" onclick="openLead(${l.id})">Editar</button><button class="btn small" onclick="openQuote(${l.id})">Orçamento</button><button class="btn small" onclick="openInteraction(${l.id})">Contato</button><button class="btn small" onclick="openTask(${l.id})">Retorno</button><button class="btn small" onclick="whatsLead(${l.id})">WhatsApp</button><button class="btn small" onclick="convertLead(${l.id})">Cliente</button></div></td></tr>`).join("")),'<button class="btn gold" onclick="openLead()">+ Novo lead</button>')+
 panel("Legenda da classificação",`<div class=classification-help><b>A — Alta prioridade</b><span>Cliente com forte intenção ou negociação avançada.</span><b>B — Boa oportunidade</b><span>Interesse claro, ainda em desenvolvimento.</span><b>C — Em acompanhamento</b><span>Contato em avaliação ou aguardando evolução.</span><b>D — Baixa prioridade</b><span>Baixa intenção no momento ou contato distante.</span></div>`);
}
function clientes(){
 $("#content").innerHTML=`<div class=searchbar><input placeholder="Pesquisar cliente por nome, CPF, telefone ou e-mail" oninput="filterRows(this.value)"></div>`+panel("Clientes",table(["Nome","CPF","Telefone","Endereço","Ações"],C.clientes.filter(c=>c.arquivado!==true).map(c=>`<tr><td><b>${esc(c.nome)}</b></td><td>${esc(cpf(c.cpf))}</td><td>${esc(phone(c.telefone))}</td><td>${esc([c.endereco,c.numero,c.cidade,c.uf].filter(Boolean).join(", "))}</td><td><button class="btn small" onclick="openClient(${c.id})">Editar</button></td></tr>`).join("")),'<button class="btn gold" onclick="openClient()">+ Cliente</button>');
}
function pipeline(){
 let stages=["Novo Lead","Qualificação","Contato realizado","Aguardando informações","Visita/Medição","Orçamento em elaboração","Orçamento enviado","Follow-up","Negociação","Fechado"];
 $("#content").innerHTML=`<div class=pipeline>${stages.map(s=>`<div class=stage><h4>${s} · ${C.leads.filter(x=>x.etapa===s).length}</h4>${C.leads.filter(x=>x.etapa===s).map(l=>`<div class=deal onclick="openLead(${l.id})"><b>${esc(l.nome)}</b><small>${esc(l.ambiente_interesse||"Projeto")}</small><small>${money(l.valor_potencial)}</small></div>`).join("")}</div>`).join("")}</div>`;
}
function agenda(){
 let arr=C.tarefas.slice().sort((a,b)=>new Date(a.vencimento)-new Date(b.vencimento));
 $("#content").innerHTML=panel("Agenda comercial",table(["Vencimento","Tarefa","Prioridade","Status","Ações"],arr.map(t=>`<tr><td>${dt(t.vencimento)}</td><td>${esc(t.titulo)}</td><td>${esc(t.prioridade)}</td><td><span class=badge>${esc(t.status)}</span></td><td><button class="btn small" onclick="completeTask(${t.id})">Concluir</button></td></tr>`).join("")),'<button class="btn gold" onclick="openTask()">+ Novo retorno</button>');
}
function orcamentos(){
 $("#content").innerHTML=`<div class=searchbar><input placeholder="Pesquisar orçamento por nº, cliente, projeto ou status" oninput="filterRows(this.value)"></div>`+panel("Orçamentos",`<div class="toolbar" style="margin-bottom:14px;align-items:end"><label style="min-width:180px;flex:1">Documentos do orçamento<select id="quoteDocumentId"><option value="">Selecione um orçamento</option>${C.orcamentos.map(o=>`<option value="${Number(o.id)}">#${Number(o.id)} — ${esc(o.cliente_nome||o.projeto||"Sem cliente")}</option>`).join("")}</select></label><button type="button" class="btn" onclick="openSelectedQuoteDocument(\'contrato\')">Gerar contrato</button><button type="button" class="btn" onclick="openSelectedQuoteDocument(\'entrega\')">Gerar termo de entrega</button></div>`+quoteTable(C.orcamentos),'<button class="btn gold" onclick="openQuote()">+ Novo orçamento</button>');
}
function openSelectedQuoteDocument(tipo){const id=Number($("#quoteDocumentId")?.value);if(!id)return alert("Selecione um orçamento para gerar o documento.");verticeDocumento(id,tipo)}
function quoteTable(arr){return table(["Nº","Cliente","Projeto","Custo interno","Lucro","Total cliente","Status","Ações"],arr.map(o=>`<tr><td>#${o.id}</td><td>${esc(o.cliente_nome||"")}</td><td>${esc(o.projeto)}</td><td>${money(o.custo_producao)}</td><td>${money(o.valor_lucro)}</td><td><b>${money(o.preco_final)}</b></td><td><span class=badge>${esc(o.status)}</span></td><td><div class=toolbar><button class="btn small" onclick="openQuote(null,${o.id})">Editar</button><button class="btn small" onclick="printQuote(${o.id})">Imprimir</button><button class="btn small" onclick="verticeDocumento(${o.id},'contrato')">Contrato</button><button class="btn small" onclick="verticeDocumento(${o.id},'entrega')">Termo de entrega</button><button class="btn small" onclick="toProduction(${o.id})">Produção</button><button class="btn small danger" onclick="deleteQuote(${o.id})">Excluir</button></div></td></tr>`).join(""))}
function producao(){
 let sts=["Aguardando produção","Em fabricação","Aguardando montagem","Montagem agendada","Concluído"];
 $("#content").innerHTML=`<div class=toolbar style="margin-bottom:12px"><button class="btn gold" onclick="openProduction()">+ Programar produção</button></div><div class=production-grid>${sts.map(s=>`<div class=production-col><b>${s}</b>${C.producao.filter(x=>x.status===s).map(p=>`<div class=production-card onclick="openProduction(${p.id})"><b>${esc(p.cliente_nome)}</b><span>${esc(p.projeto)}</span><small>Fabricação: ${date(p.inicio_previsto)} → ${date(p.conclusao_prevista)}</small><small>Montagem: ${date(p.montagem_prevista)}</small></div>`).join("")}</div>`).join("")}</div>`;
}
function materiais(){
 $("#content").innerHTML=panel("Catálogo de materiais",table(["Categoria","Material","Marca","Fornecedor","Unidade","Preço atual","Estoque","Ações"],C.materiais.map(m=>`<tr><td>${esc(m.categoria)}</td><td><b>${esc(m.nome)}</b></td><td>${esc(m.marca||"")}</td><td>${esc(m.fornecedor||"")}</td><td>${esc(m.unidade)}</td><td>${money(m.preco_custo)}</td><td>${Number(m.estoque_atual||0)}</td><td><div class=toolbar><button class="btn small" onclick="openMaterial(${m.id})">Editar</button><button class="btn small danger" onclick="deleteMaterial(${m.id})">Excluir</button></div></td></tr>`).join("")),'<button class="btn gold" onclick="openMaterial()">+ Material</button>');
}
function custos(){
 $("#content").innerHTML=panel("Custos operacionais configuráveis",table(["Custo","Categoria","Unidade","Valor","Ativo","Ações"],C.custos.map(c=>`<tr><td><b>${esc(c.nome)}</b></td><td>${esc(c.categoria||"")}</td><td>${esc(c.unidade)}</td><td>${money(c.valor)}</td><td>${c.ativo?"Sim":"Não"}</td><td><button class="btn small" onclick="openCost(${c.id})">Editar</button></td></tr>`).join("")),'<button class="btn gold" onclick="openCost()">+ Novo custo</button>');
}
function relatorios(){
 let byOrigin={};C.leads.forEach(x=>byOrigin[x.origem||"Não informado"]=(byOrigin[x.origem||"Não informado"]||0)+1);
 $("#content").innerHTML=`<div class=cards><div class="card metric"><span>Total orçado</span><b>${money(C.orcamentos.reduce((s,x)=>s+Number(x.preco_final||0),0))}</b></div><div class="card metric"><span>Lucro previsto</span><b>${money(C.orcamentos.reduce((s,x)=>s+Number(x.valor_lucro||0),0))}</b></div><div class="card metric"><span>Clientes</span><b>${C.clientes.length}</b></div><div class="card metric"><span>Em produção</span><b>${C.producao.filter(x=>x.status!=="Concluído").length}</b></div></div>${panel("Leads por origem",table(["Origem","Quantidade"],Object.entries(byOrigin).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v}</td></tr>`).join("")))}`;
}
function date(v){return v?new Date(v+"T12:00:00").toLocaleDateString("pt-BR"):"—"} function dt(v){return v?new Date(v).toLocaleString("pt-BR"):"—"}
function field(label,id,type="text",value=""){return `<label>${label}<input id="${id}" type="${type}" value="${esc(value)}"></label>`}
function selectF(label,id,opts,value=""){return `<label>${label}<select id="${id}">${opts.map(o=>`<option ${o===value?"selected":""}>${esc(o)}</option>`).join("")}</select></label>`}
function modal(title,body,onSave,saveLabel="Salvar"){ $("#modalTitle").textContent=title;$("#modalBody").innerHTML=`<div class=modal-body>${body}</div>`;$("#modalActions").innerHTML=`<button class=btn onclick="closeModal()">Cancelar</button><button id=saveModal class="btn gold">${saveLabel}</button>`;$("#modal").classList.remove("hidden");$("#saveModal").onclick=onSave}
function closeModal(){$("#modal").classList.add("hidden")}
function v(id){return $("#"+id)?.value||""} function n(id){return Number(v(id))||0}

async function lookupCEP(){
 let z=digits(v("qcep")||v("ccep"));if(z.length!==8)return;
 try{let r=await fetch(`https://viacep.com.br/ws/${z}/json/`),d=await r.json();if(d.erro)return;
 ["qend","cend"].forEach(id=>{if($("#"+id))$("#"+id).value=d.logradouro||""});["qcity","ccity"].forEach(id=>{if($("#"+id))$("#"+id).value=d.localidade||""});["quf","cuf"].forEach(id=>{if($("#"+id))$("#"+id).value=d.uf||""});
 }catch(e){}
}
function masks(prefix="q"){let a=$("#"+prefix+"cpf"),z=$("#"+prefix+"cep"),p=$("#"+prefix+"tel");if(a){a.value=cpf(a.value);a.oninput=()=>a.value=cpf(a.value)}if(z){z.value=cep(z.value);z.oninput=()=>z.value=cep(z.value);z.onblur=lookupCEP}if(p){p.value=phone(p.value);p.oninput=()=>p.value=phone(p.value)}}

async function openLead(id){
 let o=C.leads.find(x=>x.id===id)||{};
 modal(id?"Editar lead":"Novo lead",`<div class=form-grid>${field("Nome","ln","text",o.nome||"")}${field("Telefone","lt","text",o.telefone||"")}${field("E-mail","le","email",o.email||"")}${selectF("Origem","lo",(C.origens||[]).filter(x=>x.ativo).map(x=>x.nome),o.origem||"WhatsApp")}${field("Projeto / ambiente","la","text",o.ambiente_interesse||"")}${field("Valor potencial","lv","number",o.valor_potencial||"")}<label>Classificação<select id=lc><option value="">Sem classificação</option><option value="A" ${o.classificacao==="A"?"selected":""}>A — Alta prioridade</option><option value="B" ${o.classificacao==="B"?"selected":""}>B — Boa oportunidade</option><option value="C" ${o.classificacao==="C"?"selected":""}>C — Em acompanhamento</option><option value="D" ${o.classificacao==="D"?"selected":""}>D — Baixa prioridade</option></select></label>${selectF("Etapa","ls",["Novo Lead","Qualificação","Contato realizado","Aguardando informações","Visita/Medição","Orçamento em elaboração","Orçamento enviado","Follow-up","Negociação","Fechado","Perdido","Adiado"],o.etapa||"Novo Lead")}${field("Próximo contato","lp","datetime-local",o.proximo_contato_em?o.proximo_contato_em.slice(0,16):"")}</div><label style="margin-top:12px">Descrição / observações<textarea id=lobs>${esc(o.observacoes||o.descricao_projeto||"")}</textarea></label>`,async()=>{let p={nome:v("ln"),telefone:v("lt"),email:v("le"),origem:v("lo"),ambiente_interesse:v("la"),valor_potencial:n("lv"),classificacao:v("lc")||null,etapa:v("ls"),proximo_contato_em:v("lp")||null,observacoes:v("lobs")};let r=id?await sb.from("crm_leads").update(p).eq("id",id):await sb.from("crm_leads").insert(p);if(r.error)return alert(r.error.message);closeModal();await load();leads()});
}
function sameClientIdentity(a,b){const ac=digits(a.cpf||""),bc=digits(b.cpf||"");const at=digits(a.telefone||""),bt=digits(b.telefone||"");const an=String(a.nome||"").trim().replace(/\s+/g," ").toLocaleLowerCase("pt-BR"),bn=String(b.nome||"").trim().replace(/\s+/g," ").toLocaleLowerCase("pt-BR");const sameName=!!(an&&bn&&an===bn),samePhone=!!(at&&bt&&at===bt),sameCpf=!!(ac&&bc&&ac===bc);if(ac&&bc&&ac!==bc)return false;return (sameName&&samePhone)||(sameName&&sameCpf)||(sameCpf&&samePhone)}
async function findExistingClient(p,excludeId){const local=C.clientes.find(x=>String(x.id)!==String(excludeId||"")&&sameClientIdentity(x,p));if(local)return local;const {data,error}=await sb.from("clientes").select("id,nome,cpf,telefone").limit(1000);if(error)throw error;return (data||[]).find(x=>String(x.id)!==String(excludeId||"")&&sameClientIdentity(x,p))||null}
async function openClient(id){
 let o=C.clientes.find(x=>x.id===id)||{};
 modal(id?"Editar cliente":"Novo cliente",`<div class=form-grid>${field("Nome","cn","text",o.nome||"")}${field("CPF","ccpf","text",o.cpf||"")}${field("Telefone","ctel","text",o.telefone||"")}${field("E-mail","ce","email",o.email||"")}${field("CEP","ccep","text",o.cep||"")}${field("Endereço","cend","text",o.endereco||"")}${field("Número","cnum","text",o.numero||"")}${field("Cidade","ccity","text",o.cidade||"")}${field("UF","cuf","text",o.uf||"")}</div>`,async()=>{let p={nome:v("cn"),cpf:cpf(v("ccpf")),telefone:phone(v("ctel")),email:v("ce"),cep:cep(v("ccep")),endereco:v("cend"),numero:v("cnum"),cidade:v("ccity"),uf:v("cuf").toUpperCase()};let duplicate;try{duplicate=await findExistingClient(p,id)}catch(err){return alert("Não foi possível verificar cadastros existentes: "+err.message)}if(duplicate)return alert("Já existe um cliente com esses dados (cadastro #"+duplicate.id+"). Utilize o cadastro existente.");let r=id?await sb.from("clientes").update(p).eq("id",id):await sb.from("clientes").insert(p);if(r.error)return alert(r.error.message);closeModal();await load();clientes()});masks("c");
}
function materialRow(x={}){let opts=C.materiais.filter(m=>m.ativo!==false).map(m=>`<option value="${m.id}" ${String(m.id)===String(x.material_id)?"selected":""}>${esc(m.nome)} — ${esc(m.unidade)} — ${money(m.preco_custo)}</option>`).join("");return `<div class="line-item material-line"><select class=q-material onchange="materialChanged(this)"><option value="">Selecione um material...</option>${opts}</select><input class=q-mat-unit value="${esc(x.unidade||"")}" placeholder="Unid." readonly><input class=q-mat-qty type=number step=.001 min=0 value="${x.quantidade||1}" oninput="calcQuote()"><input class=q-mat-price type=number step=.01 min=0 value="${x.valor_unitario||0}" oninput="calcQuote()"><b class=q-mat-sub>${money(x.subtotal||0)}</b><button type=button class="btn small danger" onclick="this.closest('.line-item').remove();calcQuote()">×</button></div>`}
function addMaterial(x={}){$("#materialLines").insertAdjacentHTML("beforeend",materialRow(x));if(x.material_id)materialChanged($("#materialLines").lastElementChild.querySelector(".q-material"),true)}
function materialChanged(s,keep=false){let m=C.materiais.find(x=>String(x.id)===s.value),r=s.closest(".line-item");if(!m)return;r.querySelector(".q-mat-unit").value=m.unidade||"unidade";if(!keep)r.querySelector(".q-mat-price").value=Number(m.preco_custo||0).toFixed(2);calcQuote()}
function laborRow(x={}){
 let emps=C.funcionarios.filter(f=>f.ativo!==false).map(f=>`<option value="${f.id}" ${String(f.id)===String(x.funcionario_id)?"selected":""}>${esc(f.nome)}</option>`).join("");
 let funcs=C.funcoes.filter(f=>f.ativo!==false).map(f=>`<option value="${f.id}" ${String(f.id)===String(x.funcao_id)?"selected":""}>${esc(f.nome)}</option>`).join("");
 return `<div class="labor-card labor-line">
 <label>Funcionário<select class=q-employee onchange="employeeChanged(this)"><option value="">Selecione...</option>${emps}</select></label>
 <label>Função<select class=q-labor onchange="laborChanged(this)"><option value="">Selecione...</option>${funcs}</select></label>
 <label>Forma de cálculo<input class=q-labor-unit value="${esc(x.unidade||"")}" readonly></label>
 <label>Quantidade de pessoas<input class=q-labor-people type=number min=1 step=1 value="${x.quantidade_pessoas||1}" oninput="calcQuote()"></label>
 <label>Dias / horas / quantidade<input class=q-labor-time type=number step=.5 min=0 value="${x.quantidade_tempo||1}" oninput="calcQuote()"></label>
 <label>Valor unitário<input class=q-labor-price type=number step=.01 min=0 value="${x.valor_unitario||0}" oninput="calcQuote()"></label>
 <div class=labor-total><small>Subtotal</small><b class=q-labor-sub>${money(x.subtotal||0)}</b></div>
 <button type=button class="btn small danger" onclick="this.closest('.labor-card').remove();calcQuote()">Remover</button></div>`;
}
function addLabor(x={}){$("#laborLines").insertAdjacentHTML("beforeend",laborRow(x));let r=$("#laborLines").lastElementChild;if(x.funcionario_id)r.querySelector(".q-employee").value=x.funcionario_id;if(x.funcao_id)laborChanged(r.querySelector(".q-labor"),true)}
function employeeChanged(s){let emp=C.funcionarios.find(x=>String(x.id)===s.value),r=s.closest(".labor-card");if(!emp)return;if(emp.funcao_id){r.querySelector(".q-labor").value=String(emp.funcao_id);laborChanged(r.querySelector(".q-labor"))}else{r.querySelector(".q-labor-unit").value=emp.unidade||"";r.querySelector(".q-labor-price").value=Number(emp.valor||0).toFixed(2);calcQuote()}}
function laborChanged(s,keep=false){let f=C.funcoes.find(x=>String(x.id)===s.value),r=s.closest(".labor-card");if(!f)return;r.querySelector(".q-labor-unit").value=f.unidade;if(!keep)r.querySelector(".q-labor-price").value=Number(f.valor||0).toFixed(2);calcQuote()}
function projectRow(x={}){return `<div class=project-item><div class=toolbar><input class=q-project-name placeholder="Nome do projeto / móvel" value="${esc(x.nome||"")}"><button type=button class="btn small danger" onclick="this.closest('.project-item').remove()">Remover</button></div><textarea class=q-project-desc placeholder="Descrição do projeto para o cliente">${esc(x.descricao_cliente||"")}</textarea></div>`}
function addProject(x={}){$("#projectLines").insertAdjacentHTML("beforeend",projectRow(x))}
const VERTICE_CARD_RATES=[0,4.15,6.49,7.19,7.99,8.69,9.49,9.99,10.99,11.99,12.49,13.35,13.39,16.39,17.05,17.73,18.44,19.17,19.94,20.74,21.57,22.43];
function quoteCardRate(pay,parc){return pay==="Débito"?2.35:pay==="Crédito à vista"?4.15:pay==="Parcelado"?VERTICE_CARD_RATES[Math.max(2,Math.min(21,parc))]:0}
function paymentChanged(){$("#installmentFields").style.display=v("qpay")==="Parcelado"?"grid":"none";calcQuote()}
function quoteInstallmentsChanged(){const slider=$("#qparc"),out=$("#qparcValue");if(out)out.textContent=slider.value+"x";calcQuote()}
function suggestClients(){let s=v("qn").trim().toLowerCase(),b=$("#clientSuggestions");if(s.length<2){b.innerHTML="";return}let a=C.clientes.filter(c=>(c.nome||"").toLowerCase().includes(s)).slice(0,5);b.innerHTML=a.length?`<div class=suggestions>${a.map(c=>`<button type=button onclick="useClient(${c.id})"><b>${esc(c.nome)}</b><small>${esc(phone(c.telefone))}${c.cpf?" • "+esc(cpf(c.cpf)):""}</small></button>`).join("")}</div>`:""}
function useClient(id){let c=C.clientes.find(x=>x.id===id);if(!c)return;[["qn",c.nome],["qcpf",c.cpf],["qtel",c.telefone],["qe",c.email],["qcep",c.cep],["qend",c.endereco],["qnum",c.numero],["qcity",c.cidade],["quf",c.uf]].forEach(([i,x])=>$("#"+i).value=x||"");$("#clientSuggestions").innerHTML=""}
function checkCPF(){let x=digits(v("qcpf"));if(x.length!==11)return;let c=C.clientes.find(c=>digits(c.cpf)===x);if(c&&confirm(`CPF já cadastrado para ${c.nome}. Usar este cliente?`))useClient(c.id)}
function quoteForm(o={},lead=null){return `<div class=section-title>Dados do cliente</div><div class="form-grid three">${field("Nome completo","qn","text",o.cliente_nome||lead?.nome||"")}${field("CPF","qcpf","text",o.cliente_cpf||"")}${field("Telefone","qtel","text",o.cliente_telefone||lead?.telefone||"")}${field("E-mail","qe","email",o.cliente_email||lead?.email||"")}${field("CEP","qcep","text",o.cliente_cep||"")}${field("Endereço","qend","text",o.cliente_endereco||"")}${field("Número","qnum","text",o.cliente_numero||"")}${field("Cidade","qcity","text",o.cliente_cidade||"")}${field("UF","quf","text",o.cliente_uf||"")}</div><div id=clientSuggestions></div><div class=section-title>Projetos / móveis</div><div id=projectLines></div><button type=button class=btn onclick="addProject()">+ Adicionar projeto</button><div class=section-title>Materiais utilizados</div><div id=materialLines></div><button type=button class=btn onclick="addMaterial()">+ Adicionar material</button><div class=section-title>Mão de obra</div><p class="muted">Selecione o funcionário e a função. Os valores cadastrados são preenchidos automaticamente.</p><div id=laborLines></div><button type=button class=btn onclick="addLabor()">+ Adicionar mão de obra</button><div class=section-title>Custos e proposta</div><div class="form-grid three">${field("Montagem","qmont","number",o.valor_montagem||"")}${field("Frete / entrega","qfrete","number",(o.detalhes_calculo||{}).freteCliente||"")}${field("Outros custos","qop","number",(o.detalhes_calculo||{}).operacionais||"")}<label style="grid-column:1/-1">Reserva para equipamentos: <strong id="qdepreciacaoValue">${Number((o.detalhes_calculo||{}).depreciacaoPercentual??2).toLocaleString("pt-BR")}%</strong><input id="qdepreciacaoPct" type="range" min="0" max="5" step="0.5" value="${Number((o.detalhes_calculo||{}).depreciacaoPercentual??2)}" style="width:100%"></label><p class="muted" style="grid-column:1/-1">Reserva interna de 2% do valor base do projeto, ajustável, com mínimo de R$ 20. Não aparece no PDF do cliente.</p>${field("Margem (%)","qmargem","number",o.margem_lucro??30)}${field("Prazo de entrega (dias)","qprazo","number",o.prazo_entrega_dias||"")}${field("Validade (dias)","qvalid","number",o.validade_dias||15)}</div><div class=section-title>Pagamento</div><div class="form-grid three">${selectF("Forma de pagamento","qpay",["Pix","Dinheiro","Transferência","Débito","Crédito à vista","Parcelado"],o.forma_pagamento||"Pix")}<div id=installmentFields style="display:${o.forma_pagamento==="Parcelado"?"grid":"none"}"><label style="grid-column:1/-1">Número de parcelas: <strong id="qparcValue">${Math.max(2,Math.min(21,Number(o.numero_parcelas)||2))}x</strong><input id="qparc" type="range" min="2" max="21" step="1" value="${Math.max(2,Math.min(21,Number(o.numero_parcelas)||2))}" style="width:100%"></label><div class="muted" style="grid-column:1/-1">Taxa da maquininha: <strong id="qcardRate">—</strong> · automática conforme parcelas</div></div></div><div class=section-title>Observações</div><label>Observações ao cliente<textarea id=qobs>${esc(o.observacoes_cliente||"")}</textarea></label><label style="margin-top:10px">Observações internas — não impressas<textarea id=qint>${esc(o.observacoes_internas||"")}</textarea></label><div class=toolbar style="margin-top:14px"><button type=button class="btn dark" onclick="calcQuote()">Recalcular</button></div><div id=qsum></div>`}
function calcQuote(){
 let materiais=0;document.querySelectorAll(".material-line").forEach(r=>{let q=Number(r.querySelector(".q-mat-qty").value)||0,p=Number(r.querySelector(".q-mat-price").value)||0,s=q*p;materiais+=s;r.querySelector(".q-mat-sub").textContent=money(s)});
 let mao=0;document.querySelectorAll(".labor-line").forEach(r=>{let pe=Number(r.querySelector(".q-labor-people").value)||1,t=Number(r.querySelector(".q-labor-time").value)||0,p=Number(r.querySelector(".q-labor-price").value)||0,s=pe*t*p;mao+=s;r.querySelector(".q-labor-sub").textContent=money(s)});
 let mont=n("qmont"),frete=n("qfrete"),op=n("qop"),m=n("qmargem")/100,baseCusto=materiais+mao+mont+frete+op;
 let depreciacaoPercentual=Math.max(0,Math.min(100,n("qdepreciacaoPct"))),precoBase=m<1?baseCusto/(1-m):baseCusto;
 let depreciacao=depreciacaoPercentual>0?Math.max(20,precoBase*depreciacaoPercentual/100):0,custo=baseCusto+depreciacao;
 let avista=m<1?custo/(1-m):custo,lucro=avista-custo,pay=v("qpay"),parc=pay==="Parcelado"?Math.max(2,Math.min(21,Math.round(n("qparc")||2))):1,taxa=quoteCardRate(pay,parc)/100;
 let final=avista/(1-taxa),valorTaxa=final-avista,parcela=final/parc;
 if($("#qcardRate"))$("#qcardRate").textContent=(taxa*100).toFixed(2).replace(".",",")+"%";
 if($("#qdepreciacaoValue"))$("#qdepreciacaoValue").textContent=depreciacaoPercentual.toLocaleString("pt-BR")+"%";
 window.Q={materiais,mao,mont,frete,op,depreciacao,depreciacaoPercentual,custo,avista,final,lucro,margem:m*100,parcelas:parc,taxa:taxa*100,valorTaxa};
 $("#qsum").innerHTML=`<div class=quote-summary>
 <div><small>Materiais</small><b>${money(materiais)}</b></div>
 <div><small>Mão de obra</small><b>${money(mao)}</b></div>
 <div><small>Reserva para equipamentos (${depreciacaoPercentual.toFixed(1)}% do preço base, mínimo R$ 20)</small><b>${money(depreciacao)}</b></div>
 <div><small>Custo real sem margem</small><b>${money(custo)}</b></div>
 <div><small>Margem de lucro</small><b>${(m*100).toFixed(2)}%</b></div>
 <div class=profit><small>Valor do lucro</small><b>${money(lucro)}</b></div>
 <div><small>Preço à vista</small><b>${money(avista)}</b></div>
 ${taxa>0?`<div><small>Taxa da maquininha (${(taxa*100).toFixed(2)}%)</small><b>${money(valorTaxa)}</b></div><div><small>Preço no cartão</small><b>${money(final)}</b>${pay==="Parcelado"?`<small>${parc}× ${money(parcela)}</small>`:""}</div>`:""}
 </div>`;
}async function openQuote(leadId=null,id=null){let o=C.orcamentos.find(x=>x.id===id)||{},lead=C.leads.find(x=>x.id===leadId)||C.leads.find(x=>x.id===o.lead_id);window.Q=null;QM=[];QMO=[];QP=[];if(id){let a=await sb.from("orcamento_itens").select("*").eq("orcamento_id",id),b=await sb.from("orcamento_mao_obra").select("*").eq("orcamento_id",id),c=await sb.from("orcamento_projetos").select("*").eq("orcamento_id",id).order("ordem");QM=a.data||[];QMO=b.data||[];QP=c.data||[]}modal(id?`Editar orçamento #${id}`:"Novo orçamento",quoteForm(o,lead),async()=>{if(!window.Q)return alert("Clique em Recalcular antes de salvar.");let x=window.Q,projects=[...document.querySelectorAll(".project-item")].map((r,i)=>({nome:r.querySelector(".q-project-name").value.trim(),descricao_cliente:r.querySelector(".q-project-desc").value.trim(),ordem:i})).filter(x=>x.nome);if(!projects.length)return alert("Inclua pelo menos um projeto.");let mats=[...document.querySelectorAll(".material-line")].map(r=>{let mid=Number(r.querySelector(".q-material").value),m=C.materiais.find(x=>x.id===mid),q=Number(r.querySelector(".q-mat-qty").value)||0,p=Number(r.querySelector(".q-mat-price").value)||0;return{tipo:"Material",descricao:m?.nome||"Material",material_id:mid||null,nome_material:m?.nome||"",categoria_material:m?.categoria||"",unidade:r.querySelector(".q-mat-unit").value,quantidade:q,valor_unitario:p,subtotal:q*p}}).filter(x=>x.material_id);let labs=[...document.querySelectorAll(".labor-line")].map(r=>{let fid=Number(r.querySelector(".q-labor").value),f=C.funcoes.find(x=>x.id===fid),pe=Number(r.querySelector(".q-labor-people").value)||1,t=Number(r.querySelector(".q-labor-time").value)||0,p=Number(r.querySelector(".q-labor-price").value)||0;let eid=Number(r.querySelector(".q-employee").value),emp=C.funcionarios.find(x=>x.id===eid);return{funcionario_id:eid||null,funcionario_nome:emp?.nome||"",funcao_id:fid||null,funcao_nome:f?.nome||"",unidade:r.querySelector(".q-labor-unit").value,quantidade_pessoas:pe,quantidade_tempo:t,valor_unitario:p,subtotal:pe*t*p}}).filter(x=>x.funcao_id);let p={lead_id:leadId||o.lead_id||null,cliente_nome:v("qn"),cliente_cpf:cpf(v("qcpf")),cliente_telefone:phone(v("qtel")),cliente_email:v("qe"),cliente_cep:cep(v("qcep")),cliente_endereco:v("qend"),cliente_numero:v("qnum"),cliente_cidade:v("qcity"),cliente_uf:v("quf").toUpperCase(),projeto:projects.map(x=>x.nome).join(" + "),observacoes_internas:v("qint"),observacoes_cliente:v("qobs"),valor_montagem:x.mont,prazo_entrega_dias:n("qprazo")||null,validade_dias:n("qvalid")||15,custo_producao:x.custo,valor_sem_margem:x.custo,valor_antes_parcelamento:x.avista,valor_lucro:x.lucro,preco_final:x.final,valor_final_parcelado:x.final,reinvestimento_materials:x.materiais,margem_lucro:x.margem,forma_pagamento:v("qpay"),numero_parcelas:x.parcelas,taxa_parcelamento:x.taxa,condicoes_pagamento:v("qpay")==="Parcelado"?`${x.parcelas}x de ${money(x.final/x.parcelas)}`:v("qpay"),detalhes_calculo:{materiais:x.materiais,maoObra:x.mao,freteCliente:x.frete,operacionais:x.op,depreciacao:x.depreciacao,depreciacaoPercentual:x.depreciacaoPercentual,valorTaxa:x.valorTaxa,lucro:x.lucro}};let res=id?await sb.from("orcamentos").update(p).eq("id",id).select("id").single():await sb.from("orcamentos").insert({...p,status:"Rascunho"}).select("id").single();if(res.error)return alert(res.error.message);let oid=res.data.id;await Promise.all([sb.from("orcamento_itens").delete().eq("orcamento_id",oid),sb.from("orcamento_mao_obra").delete().eq("orcamento_id",oid),sb.from("orcamento_projetos").delete().eq("orcamento_id",oid)]);if(projects.length){let r=await sb.from("orcamento_projetos").insert(projects.map(x=>({...x,orcamento_id:oid})));if(r.error)return alert(r.error.message)}if(mats.length){let r=await sb.from("orcamento_itens").insert(mats.map(x=>({...x,orcamento_id:oid})));if(r.error)return alert(r.error.message)}if(labs.length){let r=await sb.from("orcamento_mao_obra").insert(labs.map(x=>({...x,orcamento_id:oid})));if(r.error)return alert(r.error.message)}let cn=digits(p.cliente_cpf),existing=null,cp={nome:p.cliente_nome,cpf:p.cliente_cpf,cpf_normalizado:cn||null,telefone:p.cliente_telefone,email:p.cliente_email,cep:p.cliente_cep,endereco:p.cliente_endereco,numero:p.cliente_numero,cidade:p.cliente_cidade,uf:p.cliente_uf};try{existing=await findExistingClient(cp)}catch(err){return alert("Orçamento salvo, mas não foi possível verificar o cliente: "+err.message)}if(existing){let cr=await sb.from("clientes").update(Object.fromEntries(Object.entries(cp).filter(([k,val])=>val))).eq("id",existing.id);if(cr.error)return alert("Orçamento salvo, mas falhou atualização do cliente: "+cr.error.message)}else if(p.cliente_nome){let cr=await sb.from("clientes").insert(cp);if(cr.error)return alert("Orçamento salvo, mas falhou cadastro do cliente: "+cr.error.message)}closeModal();await load();orcamentos()},id?"Salvar alterações":"Salvar orçamento");masks("q");$("#qn").oninput=suggestClients;$("#qcpf").onblur=checkCPF;$("#qpay").onchange=paymentChanged;$("#qparc").oninput=quoteInstallmentsChanged;$("#qdepreciacaoPct").oninput=calcQuote;(QP.length?QP:[{nome:o.projeto||lead?.ambiente_interesse||"",descricao_cliente:o.descricao_cliente||""}]).forEach(addProject);QM.forEach(addMaterial);QMO.forEach(addLabor);if(id)calcQuote()}
async function deleteQuote(id){if(!confirm(`Excluir o orçamento #${id}?`))return;let r=await sb.from("orcamentos").delete().eq("id",id);if(r.error)return alert(r.error.message);await load();orcamentos()}
async function printQuote(id){
 let o=C.orcamentos.find(x=>x.id===id);if(!o)return;
 let {data:projects,error}=await sb.from("orcamento_projetos").select("*").eq("orcamento_id",id).order("ordem");
 if(error){alert("Não foi possível carregar os projetos para impressão: "+error.message);return}
 projects=projects||[];
 let frete=Number(o.detalhes_calculo?.freteCliente||0),mont=Number(o.valor_montagem||0);
 let base=Number(o.valor_antes_parcelamento||o.preco_final||0),projeto=Math.max(0,base-frete-mont);
 let projectHtml=projects.length?projects.map((p,i)=>`<div class=project><h3>${i+1}. ${esc(p.nome)}</h3>${p.descricao_cliente?`<p>${esc(p.descricao_cliente).replace(/\n/g,"<br>")}</p>`:""}</div>`).join(""):`<div class=project><h3>${esc(o.projeto||"Móvel planejado")}</h3></div>`;
 let pay=o.forma_pagamento==="Parcelado"?`${o.numero_parcelas||1}x de ${money(Number(o.preco_final||0)/(o.numero_parcelas||1))}`:esc(o.forma_pagamento||o.condicoes_pagamento||"A combinar");
 let w=open("","_blank");w.document.write(`<!doctype html><html><head><meta charset=utf-8><title>Orçamento #${o.id}</title><style>
 body{font-family:Arial;color:#222;max-width:850px;margin:35px auto;font-size:13px}.head{display:flex;justify-content:space-between;border-bottom:3px solid #b48a35;padding-bottom:18px}.logo{font-family:Georgia;font-size:28px;letter-spacing:3px}.gold{color:#9b752b}.box{border:1px solid #ddd;padding:14px;margin:16px 0}.project{padding:10px 0;border-bottom:1px solid #eee}.project h3{margin:0 0 6px;color:#7d6028}.project p{line-height:1.55;margin:0}table{width:100%;border-collapse:collapse}td{padding:9px;border-bottom:1px solid #eee}.right{text-align:right}.total{font-size:21px;font-weight:bold}.terms{font-size:12px;line-height:1.7}.obs{white-space:pre-line}@media print{button{display:none}}</style></head><body>
 <div class=head><div><div class=logo>VÉRTICE</div><div class=gold>MARCENARIA</div></div><div><b>ORÇAMENTO #${o.id}</b><br>${new Date(o.data_criacao||Date.now()).toLocaleDateString("pt-BR")}</div></div>
 <div class=box><b>Cliente:</b> ${esc(o.cliente_nome||"")}<br><b>CPF:</b> ${esc(cpf(o.cliente_cpf))}<br><b>Telefone:</b> ${esc(phone(o.cliente_telefone))}<br><b>E-mail:</b> ${esc(o.cliente_email||"")}<br><b>Endereço:</b> ${esc([o.cliente_endereco,o.cliente_numero,o.cliente_cidade,o.cliente_uf].filter(Boolean).join(", "))}</div>
 <h2>Móvel planejado</h2>${projectHtml}
 <table><tr><td>Móvel planejado</td><td class=right>${money(projeto)}</td></tr><tr><td>Frete / entrega</td><td class=right>${money(frete)}</td></tr><tr><td><b>VALOR TOTAL</b></td><td class="right total">${money(o.preco_final)}</td></tr></table>
 <div class="box terms"><b>Prazo de entrega:</b> ${o.prazo_entrega_dias?o.prazo_entrega_dias+" dias":"A combinar"}<br><b>Validade da proposta:</b> ${o.validade_dias||15} dias<br><b>Condições de pagamento:</b> ${pay}${o.observacoes_cliente?`<br><br><b>Observações:</b><div class=obs>${esc(o.observacoes_cliente)}</div>`:""}</div>
 <p style="margin-top:55px">_________________________________________<br>Cliente / aceite</p><button onclick=print()>Imprimir / Salvar PDF</button></body></html>`);w.document.close();
}
