async function openProduction(id,quote=null){
 let o=C.producao.find(x=>x.id===id)||{},q=quote||C.orcamentos.find(x=>x.id===o.orcamento_id);
 modal(id?"Editar produção":"Programar produção",`<div class="form-grid three">${field("Cliente","pn","text",o.cliente_nome||q?.cliente_nome||"")}${field("Projeto","pp","text",o.projeto||q?.projeto||"")}${selectF("Status","ps",["Aguardando produção","Em fabricação","Aguardando montagem","Montagem agendada","Concluído","Pausado"],o.status||"Aguardando produção")}${field("Início fabricação","pi","date",o.inicio_previsto||"")}${field("Dias de fabricação","pd","number",o.dias_fabricacao||q?.dias_trabalho||"")}${field("Conclusão prevista","pc","date",o.conclusao_prevista||"")}${field("Montagem prevista","pm","date",o.montagem_prevista||"")}${field("Entrega prevista","pe","date",o.entrega_prevista||"")}${field("Responsável","pr","text",o.responsavel||"")}</div><label style="margin-top:10px">Observações internas<textarea id=po>${esc(o.observacoes||"")}</textarea></label>`,async()=>{let p={orcamento_id:q?.id||o.orcamento_id||null,lead_id:q?.lead_id||o.lead_id||null,cliente_nome:v("pn"),projeto:v("pp"),status:v("ps"),inicio_previsto:v("pi")||null,dias_fabricacao:n("pd"),conclusao_prevista:v("pc")||null,montagem_prevista:v("pm")||null,entrega_prevista:v("pe")||null,responsavel:v("pr"),observacoes:v("po")};let r=id?await sb.from("producao").update(p).eq("id",id):await sb.from("producao").insert(p);if(r.error)return alert(r.error.message);closeModal();await load();producao()});
}

function filterRows(s){s=String(s||"").toLowerCase();document.querySelectorAll("#content tbody tr").forEach(r=>r.style.display=r.innerText.toLowerCase().includes(s)?"":"none")}

async function openEmployee(id){
 let o=C.funcionarios.find(x=>x.id===id)||{};
 let opts=C.funcoes.map(f=>({label:`${f.nome} — ${money(f.valor)}/${f.unidade}`,value:String(f.id)}));
 modal(id?"Editar funcionário":"Novo funcionário",`<div class="form-grid three">${field("Nome do funcionário","en","text",o.nome||"")}<label>Função<select id=ef><option value="">Sem função padrão</option>${opts.map(x=>`<option value="${x.value}" ${String(o.funcao_id||"")===x.value?"selected":""}>${esc(x.label)}</option>`).join("")}</select></label>${field("Telefone","etel","text",o.telefone||"")}${field("Observações","eobs","text",o.observacoes||"")}</div>`,async()=>{let p={nome:v("en"),funcao_id:Number(v("ef"))||null,telefone:v("etel"),observacoes:v("eobs"),ativo:true};let r=id?await sb.from("funcionarios").update(p).eq("id",id):await sb.from("funcionarios").insert(p);if(r.error)return alert(r.error.message);closeModal();await load();custos()});
}
async function openLaborFunction(id){let o=C.funcoes.find(x=>x.id===id)||{};modal(id?"Editar função":"Nova função",`<div class=form-grid>${field("Nome da função","fon","text",o.nome||"")}${selectF("Forma de cálculo","fou",["dia","hora","fixo"],o.unidade||"dia")}${field("Valor padrão","fov","number",o.valor||"")}</div><label>Observações<textarea id=foo>${esc(o.observacoes||"")}</textarea></label>`,async()=>{let p={nome:v("fon"),unidade:v("fou"),valor:n("fov"),observacoes:v("foo"),ativo:true},r=id?await sb.from("mao_obra_funcoes").update(p).eq("id",id):await sb.from("mao_obra_funcoes").insert(p);if(r.error)return alert(r.error.message);closeModal();await load();custos()})}
async function openOrigin(id){let o=C.origens.find(x=>x.id===id)||{};modal(id?"Editar origem":"Nova origem",field("Nome da origem","on","text",o.nome||""),async()=>{let p={nome:v("on"),ativo:true},r=id?await sb.from("origens_lead").update(p).eq("id",id):await sb.from("origens_lead").insert(p);if(r.error)return alert(r.error.message);closeModal();await load();custos()})}
custos=function(){
 $("#content").innerHTML=
 panel("Funcionários / mão de obra",table(["Funcionário","Função padrão","Telefone","Ativo","Ações"],C.funcionarios.map(e=>{let f=C.funcoes.find(x=>x.id===e.funcao_id);return `<tr><td><b>${esc(e.nome)}</b></td><td>${esc(f?.nome||"—")}</td><td>${esc(phone(e.telefone))}</td><td>${e.ativo?"Sim":"Não"}</td><td><button class="btn small" onclick="openEmployee(${e.id})">Editar</button></td></tr>`}).join("")),'<button class="btn gold" onclick="openEmployee()">+ Funcionário</button>')+
 panel("Funções e valores padrão",table(["Função","Forma de cálculo","Valor","Ações"],C.funcoes.map(f=>`<tr><td><b>${esc(f.nome)}</b></td><td>${esc(f.unidade)}</td><td>${money(f.valor)}</td><td><button class="btn small" onclick="openLaborFunction(${f.id})">Editar</button></td></tr>`).join("")),'<button class="btn gold" onclick="openLaborFunction()">+ Função</button>')+
 panel("Origens de leads",table(["Origem","Ativa","Ações"],C.origens.map(o=>`<tr><td><b>${esc(o.nome)}</b></td><td>${o.ativo?"Sim":"Não"}</td><td><button class="btn small" onclick="openOrigin(${o.id})">Editar</button></td></tr>`).join("")),'<button class="btn gold" onclick="openOrigin()">+ Origem</button>')+
 panel("Outros custos operacionais",table(["Custo","Categoria","Unidade","Valor","Ativo","Ações"],C.custos.map(c=>`<tr><td><b>${esc(c.nome)}</b></td><td>${esc(c.categoria||"")}</td><td>${esc(c.unidade)}</td><td>${money(c.valor)}</td><td>${c.ativo?"Sim":"Não"}</td><td><button class="btn small" onclick="openCost(${c.id})">Editar</button></td></tr>`).join("")),'<button class="btn gold" onclick="openCost()">+ Novo custo</button>');
}
async function openInteraction(leadId){let l=C.leads.find(x=>x.id===leadId);modal("Registrar contato",`<div class=form-grid>${selectF("Canal","icanal",["WhatsApp","Telefone","Instagram","Facebook","E-mail","Presencial","Outro"],"WhatsApp")}${field("Assunto","iass","text","Contato com cliente")}</div><label>Registro do contato<textarea id=itxt></textarea></label>`,async()=>{let p={lead_id:leadId,tipo:v("icanal"),titulo:v("iass"),descricao:v("itxt")};let r=await sb.from("crm_interacoes").insert(p);if(r.error)return alert(r.error.message);closeModal();await load();leads()})}
async function openTask(leadId=null){modal("Novo retorno / tarefa",`<div class="form-grid three">${field("Título","tt","text","Retornar contato")}${field("Vencimento","tv","datetime-local","")}${selectF("Prioridade","tp",["Baixa","Normal","Alta"],"Normal")}</div>`,async()=>{let p={lead_id:leadId||null,titulo:v("tt"),vencimento:v("tv")||null,prioridade:v("tp"),status:"Pendente"};let r=await sb.from("crm_tarefas").insert(p);if(r.error)return alert(r.error.message);closeModal();await load();agenda()})}
async function completeTask(id){let r=await sb.from("crm_tarefas").update({status:"Concluída"}).eq("id",id);if(r.error)return alert(r.error.message);await load();agenda()}
function whatsLead(id){let l=C.leads.find(x=>x.id===id),num=digits(l?.telefone);if(!num)return alert("Lead sem telefone.");let br=num.length<=11?"55"+num:num;window.open(`https://wa.me/${br}?text=${encodeURIComponent("Olá, "+l.nome+"! Aqui é da Vértice Marcenaria. Estou entrando em contato para dar continuidade ao seu projeto.")}`,"_blank")}
async function convertLead(id){let l=C.leads.find(x=>x.id===id);if(!l)return;let existing;try{existing=await findExistingClient(l)}catch(err){return alert("Não foi possível verificar cadastros existentes: "+err.message)}if(existing){alert("Este lead já corresponde ao cliente "+existing.nome+".");return}let r=await sb.from("clientes").insert({nome:l.nome,telefone:l.telefone,email:l.email,cpf:l.cpf||null});if(r.error)return alert(r.error.message);let statusResult=await sb.from("crm_leads").update({status:"Convertido"}).eq("id",id).select("id");if(statusResult.error||!statusResult.data?.length){console.error("Falha ao atualizar lead após criar cliente",statusResult.error);await load();alert("O cliente foi criado, mas não foi possível atualizar o lead. Verifique os registros antes de repetir a conversão para evitar duplicidade.");leads();return}await load();alert("Cliente criado com os dados disponíveis. Complete os campos faltantes na tela Clientes.");leads()}
function financeiro(){
 let ent=C.transacoes.filter(x=>String(x.tipo).toLowerCase().includes("entrada")).reduce((s,x)=>s+Number(x.valor||x.valor_total||0),0), sai=C.transacoes.filter(x=>String(x.tipo).toLowerCase().includes("sa")).reduce((s,x)=>s+Number(x.valor||x.valor_total||0),0);
 $("#content").innerHTML=`<div class=cards><div class="card metric"><span>Entradas</span><b>${money(ent)}</b></div><div class="card metric"><span>Saídas</span><b>${money(sai)}</b></div><div class="card metric"><span>Saldo</span><b>${money(ent-sai)}</b></div></div>`+
 panel("Lançamentos",table(["Data","Tipo","Descrição","Categoria","Valor"],C.transacoes.slice().sort((a,b)=>String(b.data||b.data_inicial||"").localeCompare(String(a.data||a.data_inicial||""))).map(x=>`<tr><td>${date(x.data||x.data_inicial)}</td><td>${esc(x.tipo)}</td><td>${esc(x.descricao||"")}</td><td>${esc(x.categoria||"")}</td><td>${money(x.valor||x.valor_total)}</td></tr>`).join("")),'<button class="btn gold" onclick="openTransaction()">+ Lançamento</button>');
}
async function openTransaction(){modal("Novo lançamento",`<div class="form-grid three">${selectF("Tipo","ft",["Entrada","Saída"],"Entrada")}${field("Descrição","fd","text","")}${field("Categoria","fc","text","")}${field("Valor","fv","number","")}${field("Data","fdata","date",new Date().toISOString().slice(0,10))}${selectF("Recorrência","fr",["Único","Parcelado","Fixo"],"Único")}${field("Parcelas","fp","number",1)}</div>`,async()=>{let p={tipo:v("ft"),descricao:v("fd"),categoria:v("fc"),valor:n("fv"),valor_total:n("fv"),data:v("fdata"),data_inicial:v("fdata"),recorrencia:v("fr"),parcelas:Math.max(1,n("fp"))};let r=await sb.from("transacoes").insert(p);if(r.error)return alert(r.error.message);closeModal();await load();financeiro()})}
